#!/usr/bin/env bun
// Generate the three shipped consultation skills from the repo-only sources.
//
// Run: bun run gen:skill   (also invoked by script/build.ts before bundling)
//
// Each generated file is a shipped skill asset; skill-src/ never ships. A
// module file may hold more than one part, separated by a `<!-- part -->`
// line, because a mode's workflow section and its output template are not
// adjacent in the generated document. Each skill's module list fixes the
// emitted order and its own fragment set.

import { mkdir, readFile, rename, writeFile } from "node:fs/promises"
import { dirname, join } from "node:path"

const REPO_ROOT = join(import.meta.dir, "..")

export const SKILLS_ROOT = join(REPO_ROOT, "skill-src")

export interface SkillFragment {
  readonly name: string
  /** The placeholder left in a skill-src module, replaced at generation. */
  readonly marker: string
  readonly assetPath: string
}

export interface SkillModuleRef {
  readonly file: string
  /** 1-based part index for a module file that holds multiple parts. */
  readonly part?: number
}

export interface SkillDefinition {
  readonly name: string
  readonly srcDir: string
  readonly outputPath: string
  readonly modules: readonly SkillModuleRef[]
  readonly fragments: readonly SkillFragment[]
}

const fragment = (name: string, marker: string, asset: string): SkillFragment => ({
  name,
  marker,
  assetPath: join(REPO_ROOT, "assets", asset),
})

export const MODE_ROUTING_MARKER = "<!-- MODE-ROUTING -->"
export const CLAIM_TYPES_MARKER = "<!-- CLAIM-TYPES -->"
export const SOURCE_CRITERIA_MARKER = "<!-- SOURCE-CRITERIA -->"
export const CHANNEL_POLICY_MARKER = "<!-- CHANNEL-POLICY -->"
export const ENGINEERING_PRINCIPLES_MARKER = "<!-- ENGINEERING-PRINCIPLES -->"

export const CONSULTATION_FRAGMENTS: readonly SkillFragment[] = [
  fragment("mode-routing", MODE_ROUTING_MARKER, "principles/mode-routing.md"),
  fragment("claim-types", CLAIM_TYPES_MARKER, "principles/claim-types.md"),
  fragment("source-criteria", SOURCE_CRITERIA_MARKER, "principles/source-criteria.md"),
  fragment("channel-policy", CHANNEL_POLICY_MARKER, "principles/channel-policy.md"),
]

export const DESIGN_FRAGMENTS: readonly SkillFragment[] = [
  fragment(
    "engineering-principles",
    ENGINEERING_PRINCIPLES_MARKER,
    "principles/engineering-principles.md",
  ),
]

/** Backwards-compatible name for the core skill's fragments. */
export const SKILL_FRAGMENTS = CONSULTATION_FRAGMENTS

export const SKILLS: readonly SkillDefinition[] = [
  {
    name: "consultation",
    srcDir: join(SKILLS_ROOT, "consultation"),
    outputPath: join(REPO_ROOT, "assets/skills/consultation/SKILL.md"),
    modules: [
      { file: "core.md" },
      { file: "policies/team-orchestration.md" },
      { file: "policies/evidence-and-sources.md" },
      { file: "policies/risk-and-counter-evidence.md" },
      { file: "modes/research.md", part: 1 },
      { file: "policies/output-and-memory.md", part: 1 },
      { file: "modes/select.md" },
      { file: "modes/verify.md" },
      { file: "modes/roadmap.md" },
      { file: "modes/research.md", part: 2 },
      { file: "modes/guide.md" },
      { file: "policies/output-and-memory.md", part: 2 },
    ],
    fragments: CONSULTATION_FRAGMENTS,
  },
  {
    name: "consultation-design",
    srcDir: join(SKILLS_ROOT, "consultation-design"),
    outputPath: join(REPO_ROOT, "assets/skills/consultation-design/SKILL.md"),
    modules: [{ file: "core.md", part: 1 }, { file: "core.md", part: 2 }],
    fragments: DESIGN_FRAGMENTS,
  },
  {
    name: "consultation-doc",
    srcDir: join(SKILLS_ROOT, "consultation-doc"),
    outputPath: join(REPO_ROOT, "assets/skills/consultation-doc/SKILL.md"),
    modules: [
      { file: "core.md", part: 1 },
      { file: "core.md", part: 2 },
      { file: "policies/current-state-docs.md" },
    ],
    fragments: [],
  },
]

export const CORE_SKILL = SKILLS[0]!

export function generatedMarker(skillName: string): string {
  return `<!-- generated by script/gen-skill.ts from skill-src/${skillName}; do not edit -->`
}

/** @deprecated Use `generatedMarker("consultation")`. */
export const GENERATED_MARKER = generatedMarker("consultation")

export const SKILL_OUTPUT_PATH = CORE_SKILL.outputPath

const PART_SEPARATOR = /\n\s*<!-- part -->\s*\n/

function moduleParts(raw: string): string[] {
  return raw.split(PART_SEPARATOR).map((part) => part.trim())
}

async function loadFragment(fragment: SkillFragment): Promise<string> {
  let raw: string
  try {
    raw = await readFile(fragment.assetPath, "utf8")
  } catch {
    throw new Error(`fragment for ${fragment.marker} not found: ${fragment.assetPath}`)
  }
  const text = raw.trim()
  if (text.length === 0) {
    throw new Error(`fragment for ${fragment.marker} is empty: ${fragment.assetPath}`)
  }
  return text
}

/**
 * Replace every fragment marker with its shared source. A missing or
 * duplicated marker is a build error naming the marker: the generated skill
 * must carry each fragment exactly once, from the one source of truth.
 */
export async function injectMarkers(
  body: string,
  fragments: readonly SkillFragment[] = CONSULTATION_FRAGMENTS,
): Promise<string> {
  let result = body
  for (const entry of fragments) {
    const occurrences = result.split(entry.marker).length - 1
    if (occurrences === 0) {
      throw new Error(`skill source is missing the ${entry.marker} marker`)
    }
    if (occurrences > 1) {
      throw new Error(`skill source repeats the ${entry.marker} marker ${occurrences} times`)
    }
    const text = await loadFragment(entry)
    result = result.replace(entry.marker, () => text)
  }
  return result
}

/** Render one full skill file without touching disk. */
export async function renderSkill(skill: SkillDefinition = CORE_SKILL): Promise<string> {
  const frontMatter = (await readFile(join(skill.srcDir, "front-matter.md"), "utf8")).trim()
  if (!frontMatter.startsWith("---") || !frontMatter.endsWith("---")) {
    throw new Error(`${skill.name}/front-matter.md must be a YAML front-matter block`)
  }

  const chunks: string[] = []
  for (const entry of skill.modules) {
    const raw = await readFile(join(skill.srcDir, entry.file), "utf8")
    const parts = moduleParts(raw)
    if (entry.part !== undefined) {
      const part = parts[entry.part - 1]
      if (part === undefined || part.length === 0) {
        throw new Error(`module ${skill.name}/${entry.file} has no non-empty part ${entry.part}`)
      }
      chunks.push(part)
      continue
    }
    if (parts.length !== 1) {
      throw new Error(
        `module ${skill.name}/${entry.file} holds ${parts.length} parts; select one in the module list with \`part\``,
      )
    }
    const [only] = parts
    if (only === undefined || only.length === 0) {
      throw new Error(`module ${skill.name}/${entry.file} is empty`)
    }
    chunks.push(only)
  }

  const body = await injectMarkers(chunks.join("\n\n"), skill.fragments)

  return `${frontMatter}\n${generatedMarker(skill.name)}\n\n${body}\n`
}

/** Atomically write one generated skill file. */
export async function writeSkillFile(skill: SkillDefinition = CORE_SKILL): Promise<string> {
  const rendered = await renderSkill(skill)
  await mkdir(dirname(skill.outputPath), { recursive: true })
  const tmpPath = `${skill.outputPath}.tmp`
  await writeFile(tmpPath, rendered, "utf8")
  await rename(tmpPath, skill.outputPath)
  return skill.outputPath
}

/** Generate all three shipped skills. */
export async function writeSkillFiles(): Promise<string[]> {
  const paths: string[] = []
  for (const skill of SKILLS) paths.push(await writeSkillFile(skill))
  return paths
}

if (import.meta.main) {
  const paths = await writeSkillFiles()
  for (const path of paths) console.log(`generated skill: ${path}`)
}
